  "reasoningRetention.description": "Desactivada de forma predeterminada. Al activarla para la compactación enrutada v1/v2 con un resumen legible, el razonamiento que cabe en el menor de estos límites —el porcentaje de la ventana de contexto y el límite de tokens— vuelve como contexto histórico junto con el resumen. Si supera ese límite, se archiva localmente y se sustituye por una nota con la ruta. Valores al activarla: 20 % y 100.000 tokens. No se descifra el razonamiento privado del proveedor; la salida opaca de compactación permanece intacta.",
