  "nav.advisor": "Asesor",
  "advisor.description": "Un modelo experto independiente que revisa la tarea del agente ejecutor y devuelve recomendaciones. OpenCodex administra la consulta: el agente puede llamar a la herramienta sintética de Advisor y la política de comprobación previa también intenta una consulta automática por tarea, sin requerir su colaboración. El intento se activa cuando hay evidencia inicial de orientación: una llamada a herramientas del asistente o un resultado de herramienta posterior al último mensaje del usuario. Se evita repetir el intento por tarea en clientes con una identidad estable de conversación. Sin esa identidad, puede repetirse en cada nueva solicitud compatible.",
