  "advisor.questionOnly": "Enviar solo la pregunta del agente ejecutor",
  "advisor.questionOnlyNote": "Solo se envía la pregunta del agente ejecutor (hasta 2000 caracteres, con un aviso si se recorta), junto con una instrucción fija para el asesor. No se adjuntan el historial, los resultados de las herramientas ni el contexto de la tarea. El agente ejecutor debe incluir la información imprescindible. Las consultas automáticas se pausan y los límites de consulta se mantienen.",
  "advisor.policy.manual": "Manual — solo cuando el trabajador pregunta",
  "advisor.policy.preflight": "Prevuelo — intento de consulta automática una vez que existe evidencia de orientación",
  "advisor.policy.adaptive": "Orientación adaptativa — y consultas de reparación fallida",
  "advisor.taskLimit": "Consultas por tarea",
  "advisor.adaptiveNote": "Las consultas automáticas requieren una identidad de conversación estable. El asesoramiento inicial sigue a la evidencia de orientación (una llamada a herramientas o resultado). El asesoramiento de reparación fallida requiere una validación fallida, una edición completa del archivo y luego un nuevo fallo del mismo comando en el mismo directorio; los fallos repetidos por sí solos no califican. Las llamadas manuales también consumen el presupuesto de la tarea; las reservas caducan después de 24 horas y sobreviven a los reinicios del proxy.",
  "advisor.activity.title": "Actividad reciente del asesor",
  "advisor.activity.note": "Hasta 100 registros de este proceso, retenidos durante 24 horas. No se almacena ningún texto de tarea o consejo. Razonamiento muestra el esfuerzo asignado por el adaptador → solicitado; no reportado no confirma soporte. Los tokens muestran la entrada / salida reportada. La adopción de consejos y el costo exacto no se infieren.",
  "advisor.activity.empty": "Aún no se han registrado consultas.",
  "advisor.activity.failed": "No se pudo cargar la actividad del asesor.",
  "advisor.activity.started": "Inicio",
  "advisor.activity.trigger": "Razón / estado",
  "advisor.activity.tokens": "Entrada / salida tokens",
  "advisor.activity.duration": "Duración",
  "advisor.activity.trigger.manual": "Solicitud de trabajador",
  "advisor.activity.trigger.preflight": "Consulta inicial",
  "advisor.activity.trigger.repair_failure": "La reparación falló de nuevo",
  "advisor.activity.status.running": "Correr",
  "advisor.activity.status.ok": "Consejos devueltos",
  "advisor.activity.status.failed": "Falló",
  "advisor.activity.status.cancelled": "Cancelado",
  "advisor.activity.status.blocked": "Bloqueado",
  "advisor.timeout": "Tiempo de espera (ms)",
  "advisor.save": "Guardar la configuración del asesor",
  "advisor.saved": "Configuración del asesor guardada.",
  "advisor.loadFailed": "No se pudo cargar la configuración del asesor. ¿Está funcionando el proxy?",
  "advisor.warning.noModel": "Habilitado, pero ningún modelo experto está configurado aún — el Asesor no puede ejecutarse hasta que se configura un modelo.",
  "advisor.notices": "Notificaciones de costos y de intercambio de datos",
  "advisor.costNote": "Las consultas son llamadas modelo adicionales reales. Cada uno aparece en uso bajo el modelo de asesor, no el modelo de trabajador.",
  "advisor.privacyNote": "Aviso sobre el envío a otro proveedor: las consultas envían la conversación de la tarea y los resultados de herramientas al proveedor configurado de Advisor, que puede ser distinto del proveedor del agente ejecutor. No se eliminan los secretos que ya estén en el contenido. No habilites Advisor para tareas cuyo contenido no compartirías con ese proveedor. Activarlo no registra por sí solo este consentimiento.",
  "advisor.disclosure": "Una consulta puede enviar la tarea más reciente del usuario; el texto analizado de mensajes de usuario, asistente y desarrollador; las llamadas a herramientas con sus argumentos y resultados; el catálogo de herramientas y la identidad del agente ejecutor; el modelo de Advisor configurado y una pregunta opcional de enfoque. OpenCodex no añade claves API de proveedores, encabezados de autorización, tokens OAuth, secretos del backend, variables del entorno del proceso ni cadenas de pensamiento ocultas. No se eliminan los secretos que ya estén en el contenido de la tarea: una clave pegada, un secreto en un archivo o un token mostrado por una herramienta pueden enviarse. El proveedor de Advisor puede ser distinto del proveedor del agente ejecutor.",
  "advisor.consent.label": "Entiendo que las consultas de Advisor pueden enviar la conversación, las llamadas a herramientas y sus resultados al proveedor configurado de Advisor, que puede ser distinto del proveedor del agente ejecutor. No se eliminan los secretos que ya estén en el contenido.",
  "advisor.consent.required": "El asesor no se puede ejecutar hasta que se registre el consentimiento de intercambio de contexto. Ningún contenido de tarea se envía sin él.",
