  "startup.desktopRecovery": "OpenCodex administra este proxy. Vuelve a abrir la aplicación de escritorio y comprueba Iniciar al iniciar sesión (Start at Login). Si ya está activado, verifica que el sistema permita abrir OpenCodex al iniciar sesión (macOS: Configuración del Sistema → General → Ítems de inicio y extensiones). El servicio en segundo plano permanece desactivado mientras la aplicación administra el proxy; el shim de inicio todavía puede instalarse.",
  "startup.desktopSupervisedRecovery": "OpenCodex Desktop ejecuta este proxy, pero no se pudo verificar Iniciar al iniciar sesión (Start at Login). Actívalo en el menú de OpenCodex. Si ya está activado, verifica que el sistema permita abrir OpenCodex al iniciar sesión (macOS: Configuración del Sistema → General → Ítems de inicio y extensiones). El servicio en segundo plano permanece desactivado mientras la aplicación ejecuta el proxy; para usarlo, cierra OpenCodex y ejecuta el comando en una terminal. El shim de inicio todavía puede instalarse.",
