  "compactionRouting.effortHint": "El esfuerzo se aplica si el destino de compactación lo admite. El modelo debe aceptar la conversación completa.",
  "compactionRouting.dataNotice": "Una solicitud de compactación cubierta envía toda la conversación al proveedor del modelo seleccionado para su resumen, incluso cuando la conversación se ejecuta en otro proveedor.",
  "compactionRouting.autoNotice": "La compactación automática se ejecuta por sí sola, por lo que se puede enviar una larga conversación a ese proveedor sin que usted lo solicite.",
  "compactionRouting.providerWarning": "Con esta configuración, cada solicitud de compactación cubierta envía el contenido completo de la conversación a {provider} para su resumen.",
  "compactionRouting.comboWarning": "Con esta configuración, cada solicitud de compactación cubierta envía el contenido completo de la conversación al combo {combo} para su resumen. El combo selecciona uno de sus objetivos ({providers}) por su estrategia de enrutamiento, pero después de un fallo reintentable puede volver a intentar la misma solicitud de conversación completa en otro objetivo, para que uno o más proveedores de destino puedan recibir la conversación.",
  "compactionRouting.comboProvidersUnknown": "sus proveedores de destino configurados",
  "compactionRouting.providerWarningScoped": "Con esta configuración, solo las solicitudes de compactación cuyo modelo de origen coincida con {sources} envían el contenido completo de la conversación a {provider} para su resumen; otras solicitudes siguen utilizando su propio modelo.",
  "compactionRouting.comboWarningScoped": "Con esta configuración, solo las solicitudes de compactación cuyo modelo de origen coincida con {sources} envían el contenido completo de la conversación a combo {combo} para su resumen; otras solicitudes siguen usando su propio modelo. El combo elige uno de sus objetivos ({providers}) por su estrategia de enrutamiento, pero después de un fallo reintentable puede volver a intentar la misma solicitud de conversación completa en otro objetivo, para que uno o más proveedores de destino puedan recibir la conversación.",
  "compactionRouting.loadFailed": "No se pudo cargar la configuración de compactación.",
  "compactionRouting.saved": "Se guardó la configuración de compactación.",
  "compactionRouting.saveFailed": "No se pudo salvar. Tus cambios están aquí; inténtalo de nuevo.",
  "memoryModels.title": "Enrutamiento de memoria",
  "memoryModels.description": "Codex crea memorias después de cada sesión terminada. Elige un modelo para cada fase o conserva su ruta existente.",
  "memoryModels.infoLabel": "¿Qué son el extracto y la consolidación?",
  "memoryModels.info": "Codex convierte las sesiones terminadas en memoria en dos pasos. Extract lee una sesión terminada y anota lo que sucedió: una nota por sesión, por lo que hace muchas llamadas pequeñas. La consolidación toma esas notas y las escribe en los archivos de memoria que Codex lee al comienzo de sus próximas sesiones. Se ejecuta raramente, pero edita archivos. Cada paso pide su propio modelo, por lo que se enumeran por separado aquí.",
  "memoryModels.extract": "Extracción",
  "memoryModels.extractHint": "Resume cada sesión terminada en una nota de memoria. Se ejecuta una vez por sesión.",
  "memoryModels.consolidation": "Consolidación",
  "memoryModels.consolidationHint": "Combina las notas de memoria en los archivos que Codex lee después. Se ejecuta con poca frecuencia y edita archivos.",
  "memoryModels.model": "Modelo",
  "memoryModels.effort": "Esfuerzo de razonamiento",
  "memoryModels.off": "Desactivado",
  "memoryModels.defaultEffort": "Codex por defecto",
  "memoryModels.dataNotice": "El modelo elegido recibe los datos de su fase: la sesión terminada para Extracción y las notas de memoria para Consolidación.",
  "memoryModels.accountNotice": "Solo una fase se enruta aquí; la otra mantiene su ruta existente. Shadow Call Intercept también puede enviar las llamadas de memoria de esa fase a su modelo configurado.",
  "memoryModels.loadFailed": "No se pudo cargar la configuración de la memoria.",
  "memoryModels.saved": "Se guardó la configuración de memoria.",
  "memoryModels.saveFailed": "No se pudo salvar. Tus cambios están aquí; inténtalo de nuevo.",
  "dash.shadowCallIntercept": "Interceptación de llamadas auxiliares",
  "shadowCall.memoryLabel": "Memoria: Terra",
  "shadowCall.sourceCoveredShort": "Cubierto por {prefix}",
  "shadowCall.sourceRequired": "Debe permanecer activado",
  "dash.shadowCallInterceptHint": "Intercepta las llamadas auxiliares de Codex App en segundo plano para títulos, mensajes de commit y coordinación de habilidades. Elige los modelos de origen a continuación. La consolidación de memoria suele ejecutarse en Terra y sigue el routing de memoria si está configurado.",
  "dash.shadowCallWarning": "⚠ Al activarlo, las solicitudes de cada origen seleccionado ({models}) se redirigen al modelo elegido. Terra se activa por separado. El routing de memoria tiene prioridad para la consolidación.",
  "dash.shadowCallOriginal": "Original",
  "dash.shadowCallModel": "Modelo de reemplazo",
  "dash.shadowCallTooltip": "Codex App realiza llamadas en segundo plano para generar títulos de conversaciones y mensajes de commit, y coordinar habilidades. El modelo auxiliar ha variado entre versiones del cliente, por lo que OpenCodex puede interceptar varios orígenes. Elige los que quieras redirigir. Terra consolida la memoria y está desactivado inicialmente porque Codex también lo usa para tareas ordinarias. Si hay un modelo de consolidación configurado en el routing de memoria, esa ruta tiene prioridad. Al menos un origen debe quedar activo. Usa el interruptor principal para dejar de interceptar llamadas en segundo plano.",
  "shadowCall.sources": "Orígenes interceptados",
  "shadowCall.sourceHelper": "Auxiliar",
  "shadowCall.sourceMemory": "Memoria",
  "shadowCall.sourceLegacy": "Anterior",
  "shadowCall.sourceCustom": "Personalizado",
  "shadowCall.sourceHint": "Solo se interceptan los orígenes habilitados. Al menos uno debe quedar activo. Usa el interruptor principal para dejar de interceptar llamadas en segundo plano. El routing de memoria tiene prioridad para la consolidación si está configurado.",
  "shadowCall.sourceCovered": "El prefijo personalizado {prefix} cubre este origen. Elimínalo o restringe su alcance en config.json para cambiar este origen por separado.",
  "shadowCall.sourceLastRequired": "Al menos un origen debe quedar activo. Usa el interruptor principal para dejar de interceptar llamadas en segundo plano.",
  "models.shadowCallIntercept": "Interceptación de llamadas auxiliares",
  "models.shadowCallInterceptHint": "Intercepta las llamadas auxiliares de Codex App en segundo plano para títulos, mensajes de commit y coordinación de habilidades. Elige los modelos de origen a continuación. La consolidación de memoria suele ejecutarse en Terra y sigue el routing de memoria si está configurado.",
  "models.shadowCallSaveFailed": "No se pudo guardar la configuración de llamadas en segundo plano.",
  "models.shadowCallTargetInvalid": "El destino de reemplazo coincide con un origen activo. Elige otro modelo.",
  "models.shadowCallSourceInvalid": "La selección de orígenes no es válida. Elige al menos uno sin espacios ni prefijo de proveedor.",
  "models.autoReviewOverride": "Anulación de revisión automática",
  "models.autoReviewOverrideHint": "Elige el modelo que Codex utiliza para la revisión automática (el revisor de aprobación). Aplicado a cada fila de catálogo en sincronización; un autoReviewModel con alcance de proveedor todavía tiene prioridad en sus propias filas.",
