  "dash.multiAgentGuidance": "Dile a Codex cómo dividir el trabajo",
  "dash.multiAgentGuidanceHint": "Envía una nota corta diciéndole a Codex cómo trabajar manualmente con subagentes. En v2 nombra los modelos que puede usar y cuáles preferir; en v1 solo se aplica en el esfuerzo de razonamiento máximo o ultra. Fuera, no se agrega ninguna nota.",
