  "dash.effortCapLabel": "Límite de esfuerzo ultra V2",
  "dash.subagentEffortCapLabel": "Límite de esfuerzo del subagente V2",
  "dash.effortCapHelp": "Limita el esfuerzo de razonamiento de los turnos V2 en modo ultra. Las solicitudes entrantes con esfuerzo máximo se reducen al nivel elegido. El límite de subagentes solo afecta a los subagentes creados. Los límites reducen el esfuerzo, nunca lo aumentan. Si un modelo no admite el nivel elegido, se usa el nivel compatible más cercano que no lo supere.",
