  "oauthTos.elevatedTitle": "{provider}: puente no oficial OAuth",
  "oauthTos.anthropicBody": "Esto conecta una suscripción Claude a través del proxy de terceros de OpenCodex. Anthropic no ha respaldado esta conexión ni la agrupación automatizada de cuentas; el acceso depende de sus términos y aplicación actuales.",
