  "oauthTos.elevatedBody": "OpenCodex conecta {provider} a través de una ruta no oficial OAuth. Use el cliente oficial cuando sea posible; el tráfico inusual o automatizado puede ser tratado como abuso y el acceso puede ser limitado o suspendido.",
  "oauthTos.saferPath": "Opción más segura: configura una clave API en OpenCodex.",
