  "oauthTos.anthropicTitle": "Claude conexión de suscripción",
  "oauthTos.anthropicConditions": "Usa una cuenta que te pertenezca o que tengas autorización para usar. Usar el cliente original de Claude Code con una persona que supervise la sesión es distinto de enviar tokens de una suscripción a través de otros clientes. OpenCodex también admite esos otros clientes, por lo que establecer esta conexión no garantiza que todos los usos estén permitidos. Las integraciones compatibles con Agent SDK se tratan por separado.",
  "oauthTos.anthropicSaferPath": "Para otros clientes o automatización desatendida, configura una clave API de Anthropic.",
  "oauthTos.anthropicAcknowledge": "Entiendo que esta es una conexión de suscripción de terceros y verificaré los términos aplicables.",
  "oauthTos.anthropicContinue": "Continuar con la suscripción a Claude",
  "subagentSurface.selectionTitle": "¿Cambiar la superficie del subagente a {mode}?",
  "subagentSurface.selectionBody": "En {mode}, los modelos de ChatGPT que usan la interfaz v2 —Sol y Terra en base, y todos los modelos en v2— entregan su tarea a un modelo enrutado como Grok o Claude cifrada para el backend de ChatGPT. El modelo enrutado no puede leerla. Esa delegación falla con unreadable_encrypted_agent_task hasta que se corrija en origen. v1 permite delegar entre proveedores de forma fiable.",
  "subagentSurface.advisoryTitle": "v1 es ahora la interfaz predeterminada de subagentes",
  "subagentSurface.advisoryBody": "Esta instalación usa {mode}. En la interfaz v2, un modelo de ChatGPT entrega al modelo enrutado una tarea cifrada que este no puede leer, por lo que falla la delegación entre proveedores. Recomendamos v1 hasta que se corrija en origen. Tu configuración actual no cambia hasta que elijas.",
  "subagentSurface.continue": "Continuar",
  "subagentSurface.switchToV1": "Cambiar a v1",
  "subagentSurface.learnMore": "Por qué falla esto",
