  "models.tabsLabel": "Interfaces de modelos",
  "models.subtitle.combos": "Grupos ordenados de modelos que responden como un solo id. Encadena los objetivos con conmutación por error o distribuye la carga con una estrategia de equilibrio.",
  "models.subtitle.compatibility": "Matriz de veredicto de compatibilidad de solo lectura a partir de pruebas de proyección de laboratorio.",
  "models.subtitle.routing": "Perfiles de políticas, evaluación de ejecución en seco y análisis de enrutamiento respaldado por fuentes.",
  "models.subtitle": "Elige qué modelos ve Codex: los GPT nativos por paso directo y los modelos enrutados, agrupados por proveedor. Pulsa un encabezado para contraerlo. Los modelos ocultos no aparecen en el catálogo ni en el selector, pero puedes llamarlos directamente con su identificador exacto.",
  "models.delivery.title": "Cómo llegan los cambios a Codex",
  "models.delivery.chip.saved": "Guardado aquí",
  "models.delivery.chip.savedHub": "Guardado en el hub",
  "models.delivery.chip.synced": "{time} sincronizado",
  "models.delivery.chip.syncedUnknown": "Sin sincronización registrada",
  "models.delivery.chip.loaded": "Codex lo carga en el reinicio",
  "models.delivery.saved.title": "Guardado en este proxy",
  "models.delivery.saved.body": "Guardar en esta página actualiza el catálogo que este proxy de OpenCodex entrega a Codex y que muestra su selector de modelos. La confirmación de guardado indica que este paso terminó.",
  "models.delivery.savedHub.title": "Guardado en el hub",
  "models.delivery.savedHub.body": "Esta máquina está conectada a un concentrador OpenCodex compartido, por lo que guardar aquí cambia el catálogo del concentrador. La confirmación después de guardar significa que el concentrador lo tiene; esta máquina todavía tiene que descargarlo.",
  "models.delivery.synced.title": "Sincronizado con esta máquina",
  "models.delivery.synced.bodyAt": "Esta máquina descargó por última vez el catálogo del concentrador en {time} y lo escribió donde Codex lo lee. Ese tiempo solo te dice cuándo se ejecutó la descarga. Si guardó en el concentrador después de él, esta máquina mantiene la lista anterior hasta la siguiente sincronización.",
  "models.delivery.synced.bodyUnknown": "Esta máquina aún no tiene descarga registrada del catálogo de concentradores, por lo que es posible que Codex todavía esté leyendo una lista anterior. La siguiente sincronización lo descarga.",
  "models.delivery.loaded.title": "Cargado por Codex",
  "models.delivery.loaded.body": "Codex lee el catálogo cuando se inicia, por lo que una ventana Codex que ya estaba abierta mantiene su lista de modelos antiguos. OpenCodex no puede mirar dentro de un Codex en ejecución para ver qué lista utiliza. Cuando puede saber que Codex comenzó antes de su cambio, aparece un aviso de reinicio encima de las pestañas.",
  "models.delivery.hint": "Si un modelo que encendió no se muestra en Codex, presione Recargar modelos de Codex en la parte superior derecha de esta página, luego vuelva a abrir Codex.",
  "models.nativeGroupLabel": "OpenAI nativo",
  "models.nativeHint": "Los modelos Passthrough utilizan la opción de cuenta Pool o Direct seleccionada en Proveedores. Al alternar uno solo se oculta del selector Codex (la entrada del catálogo se mantiene, por lo que volver a habilitarlo lo restaura exactamente). Agregar un modelo aquí registra un selector `openai/<model>` enrutado, no una nueva identificación de paso a través.",
