  "models.contextCapLabel": "Ventana o límite predeterminado",
  "models.v2Label": "Subagente",
  "models.shadowCallOriginal": "{models} →",
  "models.v2DocsLink": "¿Qué es v1 / v2?",
  "models.v2Mode_v1": "v1",
  "models.v2Mode_default": "base",
  "models.v2Mode_v2": "v2",
  "models.v2Mode_v2-plaintext": "V2 · tareas en texto claro",
  "models.v2ModeDesc_v1": "Todos los modelos → superficie v1",
  "models.v2ModeDesc_default": "Valores predeterminados de flujo ascendente (sol/terra-v2, luna-v1)",
  "models.v2ModeDesc_v2": "Todos los modelos → superficie v2",
  "models.v2PlaintextOn": "Está configurado el envío de tareas en texto claro (experimental)",
  "models.keepNativeOnV1": "Mantener ChatGPT en v1",
  "models.keepNativeOnV1Hint": "ChatGPT cifra las tareas secundarias de v2 solo cuando un padre nativo de ChatGPT permanece en v2, por lo que Grok y Claude no pueden leerlas. Encienda esto para mantener Sol/Terra en v1 y evitar ese cifrado. Los padres enrutados mantienen v2.",
  "models.v2Help": "Controla el modo multiagente de todos los modelos.\n\nv1: Agente clásico de un solo hilo. Todos los modelos usan la interfaz de colaboración v1.\nbase: Valores predeterminados del proveedor. Sol y Terra usan v2; Luna usa v1; los demás siguen la opción de Codex.\nv2: Agente con varios hilos mediante spawn_agent. Todos los modelos usan la interfaz de colaboración v2.\nV2 · tareas en texto claro: Variante opcional de v2. Todos los modelos conservan la interfaz v2 y se envía en texto claro el contenido de las tareas compatibles.\n\nEn v2, «Mantener ChatGPT en v1» deja a Sol y Terra en la interfaz v1 para que puedan iniciar Grok o Claude. ChatGPT cifra las tareas de subagentes en v2; los modelos enrutados no pueden leerlas. Los agentes principales enrutados se mantienen en v2.\n\nLos cambios de catálogo se aplican a las sesiones nuevas. Mientras esté habilitado, el compilador también se aplica a solicitudes canónicas de ChatGPT compatibles que se envíen después desde sesiones V2 existentes. Al desactivarlo no se borran las copias conservadas. v1 sigue disponible.",
  "plaintextV2.title": "¿Habilitar V2 · tareas en texto claro?",
  "plaintextV2.body": "Experimental. Los mensajes de tareas de colaboración compatibles usan texto claro en la aplicación y pueden quedar en el historial de Codex, las solicitudes al proveedor elegido y los datos locales de respuestas y diagnóstico. HTTPS y la autenticación permanecen activos. No se descifran textos existentes ni se reescribe el historial guardado.",
  "plaintextV2.caveat": "Si no se puede reescribir una solicitud de forma segura, se envía tal cual y la delegación aún puede fallar.",
  "plaintextV2.scope": "Los cambios de catálogo se aplican a las sesiones nuevas. Mientras esté habilitado, el compilador también se aplica a solicitudes canónicas de ChatGPT compatibles que se envíen después desde sesiones V2 existentes. Al desactivarlo no se borran las copias conservadas. v1 sigue disponible.",
  "plaintextV2.acknowledge": "Entiendo que el texto de las tareas puede conservarse en texto claro.",
  "plaintextV2.confirm": "Habilitar tareas en texto claro",
  "dash.multiAgent": "Subagente",
  "dash.codexDesktopAuthless": "Abrir Codex sin iniciar sesión",
  "dash.codexDesktopAuthlessHint": "Desactivado de forma predeterminada. Omite el inicio de sesión independiente de Desktop para las conexiones locales compatibles. El proveedor de origen sigue necesitando credenciales. Reinicia Codex después de cambiar esta opción. Las funciones de Desktop que requieren una cuenta pueden no estar disponibles.",
  "dash.codexClientCompaction": "Usa la compactación del lado del cliente",
  "dash.codexClientCompactionHint": "Desactivada de forma predeterminada; solo en conexiones de bucle local autenticadas. Las futuras compactaciones guardan resúmenes portátiles en texto sin cifrar mientras siguen activos OpenCodeX y el enrutamiento de proveedores V2; el proveedor configurado puede procesarlos y consumir cuota. El historial no cambia y los hilos existentes siguen pasando por el proxy mediante la opción openai_base_url que administra OpenCodeX. Si configuraste esa línea por tu cuenta, se conserva y esos hilos usan tu destino. El historial ocx1 existente sigue siendo recuperable; recupera un hilo por separado solo antes de reproducirlo en Codex nativo. Reinicia Codex después de cambiar esta opción.",
  "dash.codexRemoteHistoryHint": "El enrutamiento de la tabla del proveedor puede ocultar los hilos etiquetados con openai existentes en algunas listas remotas móviles. El historial no se elimina. El cliente remoto debe enumerar todos los proveedores; este conmutador no repara ese filtro de cliente.",
  "models.v2Conflict": "[agents] tiene configurado max_concurrent_threads_per_session / max_threads; codex se negará a iniciar. Elimina ese ajuste de config.toml.",
  "models.v2Applied": "Modo de subagentes actualizado. El catálogo cambia para sesiones nuevas. Con el texto claro habilitado, también pueden verse afectadas solicitudes posteriores compatibles de sesiones V2 existentes. Reinicia Codex App para actualizar el selector.",
