  "sub.forceTitle": "Usar un solo modelo para todos los subagentes",
  "sub.forceModel": "Modelo de subagente Claude Code",
  "sub.forceChoose": "Elige un modelo expuesto",
  "sub.forceHelp": "Se aplica a los agentes integrados y de plugins, incluidos Explore y Plan, y reemplaza los modelos elegidos en cada llamada. Las bifurcaciones y las skills con model: inherit conservan el modelo de la conversación principal. No afecta al modelo principal ni a los sidecars Haiku/small-fast.",
  "sub.forceScope": "Desactivado de forma predeterminada. Se aplica desde el próximo inicio enrutado con ocx claude, no al ejecutar claude directamente. Tienen prioridad las variables exportadas por la shell; env en settings.json puede sustituirlas. El estado solo comprueba la CLI y la configuración de usuario del servidor, no otras shells ni configuraciones del proyecto.",
  "sub.forceInvalid": "El destino configurado no está disponible. Se omitirá la anulación de inicio; elige un modelo expuesto o desactiva esta opción.",
  "sub.forceOld": "Claude Code es más antiguo que 2.1.257: se ignora FORCE; solo se aplica el valor predeterminado de subagente no forzado.",
  "sub.forceUnknown": "La versión Claude Code es desconocida. El soporte de fuerza requiere la versión 2.1.257 o posterior.",
  "sub.forceOverride": "Anulado por settings.json: su env contiene un modelo de subagente o la configuración FORCE. OpenCodex no lo modifica.",
  "sub.forceSettingsUnknown": "No se pudo inspeccionar settings.json. Se desconoce el estado de anulación de la configuración.",
  "sub.forceSaved": "Guardado. Tendrá efecto la próxima vez que inicies ocx claude con enrutamiento.",
  "sub.subtitle": "Codex de {cmd} anuncia solo los primeros 5 modelos (por prioridad) como anulaciones. Recoger hasta 5 aquí — nativo gpt o enrutado — y opencodex establece su prioridad de catálogo por lo que exactamente estos plomo. Cualquier otro modelo todavía se puede llamar por su nombre exacto; esto solo controla lo que se muestra.",
