  "integrations.semantics.qoder": "Administra los proveedores y modelos personalizados de OpenCodex en ~/.qoder/settings.json. Requiere acceso por bucle local. Se conserva el resto de la configuración; Deshacer restaura la instantánea.",
  "integrations.semantics.t3code": "Añade una instancia del proveedor Claude llamada opencodex a ~/.t3/userdata/settings.json (T3CODE_HOME permite cambiar su ubicación). Los modelos enrutados aparecen en el selector de T3 Code. Las conversaciones de Codex solo usan el proxy si la integración de Codex está habilitada y T3 Code comparte el mismo CODEX_HOME. Requiere acceso por loopback. Se conserva el resto de la configuración; Deshacer restaura la copia guardada.",
