  "integrations.cursor.title": "Cursor",
  "integrations.cursor.intro": "Cursor Private Inference dirige su agente a nivel local y habla con opencodex en bucle. Regular Cursor no puede: su backend llama al endpoint personalizado y necesita un HTTPS URL. Esta página nunca escribe a Cursor; pegar los valores de abajo en Cursor Tú mismo.",
  "integrations.cursor.loading": "Lectura Cursor estado…",
