  "integrations.cursor.installerIntro": "Cursor Private Inference es una compilación de modo local separada. El canal de actualización de Cursor anuncia su instalador, versión {version}; instálelo, luego pegue la clave Base URL y API a continuación en Configuración > Modelos > Gateway.",
