  "integrations.cursor.ladderFromStatic": "Las escaleras de razonamiento son un espejo estático de Cursor 3.18.25 (no se encontró ningún paquete de inferencia privada legible). El contexto muestra el valor predeterminado y la ventana opt-in.",
