  "integrations.dialog.codex.title": "¿Deshabilitar la integración Codex?",
  "integrations.dialog.codex.changes": "opencodex eliminará su enrutamiento de {path}, eliminará su perfil generado, restaurará el catálogo de modelos nativo y volverá a etiquetar los hilos reanudables para Codex nativo.",
  "integrations.dialog.codex.breakage": "El comando codex sin envoltorio se conectará directamente a OpenAI y los modelos enrutados desde otros proveedores desaparecerán de Codex. El proxy y /v1/responses seguirán disponibles para otros clientes.",
  "integrations.dialog.codex.undo": "Al volver a activarlo, se reconstruye el catálogo enrutado de los modelos disponibles en ese momento e inyecta Codex nuevamente. El historial de reanudación se hace utilizable en la dirección correspondiente, pero sus archivos no se restauran byte por byte.",
  "integrations.dialog.codex.sideEffect": "Si elegiste un modelo raíz enrutado después de que opencodex inyectara la configuración, desactivar la integración elimina esa selección. Al reactivarla no se puede reconstruir: debes volver a elegir el modelo. Si un model_provider externo administra Codex, opencodex solo elimina su registro de cambios obsoleto y conserva la configuración, el catálogo y el historial.",
  "integrations.dialog.codex.confirm": "Desactivar",
  "integrations.dialog.grok.title": "¿Deshabilitar la integración Grok Build?",
  "integrations.dialog.grok.changes": "Solo el bloque marcado con opencodex se eliminará de {path}. El contenido escrito fuera del bloque permanecerá sin cambios.",
  "integrations.dialog.grok.breakage": "Deshabilitar elimina los alias de modelo opencodex de Grok Build. Los modelos utilizados con su cuenta xAI permanecen disponibles.",
  "integrations.dialog.grok.undo": "Si opencodex se está ejecutando en una dirección de loopback, volver a activar escribe un nuevo bloque de los modelos disponibles actualmente.",
  "integrations.dialog.grok.confirm": "Desactivar",
  "integrations.dialog.desktop.title": "¿Desactivar la integración con Claude Desktop?",
  "integrations.dialog.desktop.changes": "Si {path} contiene un perfil de puerta de enlace administrado por opencodex, Desktop primero seleccionará un nuevo perfil estándar sin credenciales y luego eliminará el perfil anterior y la copia de seguridad.",
  "integrations.dialog.desktop.breakage": "Claude Desktop volverá a utilizar Claude estándar en lugar de modelos enrutados mediante opencodex.",
  "integrations.dialog.desktop.undo": "Al volver a activarlo, se regenera el perfil opencodex de las asignaciones de modelo guardadas.",
  "integrations.dialog.desktop.restart": "Claude Desktop lee esta configuración solo en el inicio. Retírelo completamente y vuelva a abrirlo para que este cambio tenga efecto.",
  "integrations.dialog.desktop.confirm": "Desactivar",
  "integrations.native.msg.nonLoopbackRemoved": "Grok Build se puede registrar automáticamente solo mientras opencodex se ejecuta en una dirección de loopback. El bloque anterior que apuntaba a loopback fue eliminado.",
  "integrations.native.msg.nonLoopbackRemovedNoop": "Grok Build se puede registrar automáticamente solo mientras opencodex se ejecuta en una dirección de loopback. No había ningún bloque anterior que eliminar.",
  "integrations.native.msg.nonLoopbackSuperseded": "Grok Build se puede registrar automáticamente solo mientras opencodex se ejecuta en una dirección de loopback. Mientras tanto, otro proceso escribió un nuevo bloque, por lo que el bloque ahora en el archivo no fue creado por esta solicitud.",
  "integrations.native.error.orphanedMarker": "{path} tiene un marcador de inicio opencodex pero no un marcador de fin. El archivo se dejó sin cambios porque opencodex no puede determinar dónde termina su bloque.",
  "integrations.native.error.homeMismatch": "El servicio de inicio instalado no coincide con el hogar actual, por lo que el archivo se dejó sin cambios.",
  "integrations.native.error.notInstalled": "Grok Build no está instalado, así que no hay nada que cambiar.",
  "integrations.native.error.configBusy": "La configuración se guarda en otro lugar y no se puede cambiar. Vuelva a intentarlo en breve.",
