  "integrations.semantics.gajae": "Se aplica a una nueva sesión o al abrir /model.",
  "integrations.semantics.dsh": "OpenCodex solo administra el proveedor opencodex de la fila llm-pi-ai en $DSH_HOME/profiles/desktop/cordis.patch.yml, el perfil Desktop que lee DSH 0.1.7+ ($DSH_HOME/settings.yaml mientras ese perfil no exista). DSH recarga este proveedor en caliente; tu modelo predeterminado y deepseek-official no cambian. Actualmente solo se admite la interfaz de bucle local; no se escribe ninguna credencial real.",
  "integrations.semantics.mcode": "Solo administra custom_provider.opencodex. Su modelo predeterminado y el inicio de sesión MiniMax permanecen sin cambios.",
  "integrations.semantics.zcode": "Gestiona solo provider.opencodex en ~/.zcode/v2/config.json. Su inicio de sesión de Z.ai y otros proveedores permanecen sin cambios. Reinicia ZCode después de los cambios.",
  "integrations.semantics.commandcode": "Administra solo la entrada del proveedor OpenCodex en ~/.commandcode/providers.json.. Sus otros proveedores y configuración permanecen sin cambios.",
  "integrations.semantics.prime": "Gestiona solo providers.opencodex en models.json de Prime Agent — ~/.prime/agent a menos que PRIME_AGENT_CODING_AGENT_DIR lo redirija. Sus otros proveedores y modelos anulados permanecen sin cambios. Se aplica a nuevas sesiones.",
  "integrations.semantics.aside": "Solo administra providers.opencodex en ~/.aside/u/<id>/models.json de este perfil. Tus otros proveedores no cambian. Cierra Aside por completo y vuelve a abrirlo después de aplicar los cambios.",
  "integrations.semantics.raycast": "Agrega una entrada de proveedor OpenCodex al providers.yaml de Raycast para que cada modelo enrutado aparezca en el selector de modelos de IA de Raycast. Se requiere Raycast Pro.",
  "integrations.semantics.omo": "Gestiona solo providers.opencodex en models.json de omo — ~/.omo/agent a menos que OMO_CODING_AGENT_DIR, SENPI_CODING_AGENT_DIR o PI_CODING_AGENT_DIR lo redirija. Sus otros proveedores permanecen sin cambios. Se aplica a nuevas sesiones.",
