  "integrations.semantics.cline": "Gestiona OpenCodex en Cline CLI providers.json y models.json. Detenga Cline antes de cambiar o sincronizar estos archivos y, a continuación, reinicie. Deshacer restaura ambos originales. Su proveedor predeterminado permanece sin cambios; seleccione OpenCodex en Cline.",
  "integrations.semantics.kilo": "Solo administra provider.opencodex en la configuración global de Kilo: el primer archivo existente entre kilo.jsonc, kilo.json, opencode.jsonc, opencode.json y config.json en ~/.config/kilo (XDG_CONFIG_HOME cambia la ubicación de ese directorio; se crea kilo.jsonc si no existe ninguno). Las demás claves no cambian. Aplicar reescribe el archivo completo, por lo que no se conservan los comentarios ni las comas finales. Selecciona opencodex/<model> en Kilo.",
