  "codexAuth.creditsAfterLimitHint": "Desactivado de forma predeterminada: una cuenta cuya ventana de uso llega al 100% se apaga hasta que se restablece, por lo que sus créditos ChatGPT no se gastan. Encienda una cuenta para que siga funcionando de sus créditos. Comienzan nuevas cuentas.",
  "codexAuth.creditsAfterLimitAria": "Usar créditos después del límite de uso para {email}",
  "codexAuth.creditsAfterLimitMainHint": "El bloqueo duro de la cuenta principal (activado por defecto) aún lo detiene primero. Apague el candado para permitir que la cuenta principal gaste créditos.",
  "codexAuth.creditSpend": "Usar créditos",
