  "codexAuth.creditsOn": "Utiliza créditos",
  "codexAuth.creditsOnSucceeded": "{email} puede usar créditos después de su límite de uso.",
  "codexAuth.creditsOffSucceeded": "{email} se cambiará a su límite de uso, por lo que sus créditos se mantienen.",
  "codexAuth.creditsUpdateFailed": "No se pudo actualizar la configuración de créditos para {email}. Nada había cambiado.",
  "codexAuth.creditsAllOnSucceeded": "Cada cuenta puede usar créditos después de su límite de uso.",
