  "codexAuth.pinned": "FIJADA",
  "codexAuth.pinnedHint": "Usted seleccionó esta cuenta a mano, por lo que un orden de selección más alto no pasará de ella. El pin dura hasta que se agote esta cuenta, seleccione otro o cambie cualquier orden de selección.",
  "codexAuth.unpinHint": "Selecciona de nuevo para soltar el pin y volver a la selección automática.",
  "codexAuth.unpinTitle": "¿Liberar el pin?",
  "codexAuth.unpinDesc": "Tiene efecto inmediato. Los hilos ya vinculados a una cuenta y las solicitudes en vuelo mantienen su cuenta capturada; las solicitudes nuevas o no vinculadas seleccionan una cuenta automáticamente del orden de selección y los umbrales.",
  "codexAuth.unpinAction": "Alfiler de liberación",
  "codexAuth.unpinned": "La selección automática — está de vuelta en",
  "codexAuth.unpinFailed": "No se pudo confirmar la liberación del pin. Actualizar cuentas y comprobar la selección actual antes de volver a intentarlo.",
  "codexAuth.unpinChanged": "El pin cambió mientras esta confirmación estaba abierta. Actualizar cuentas y revisar la selección actual antes de lanzar un pin.",
