  "accountPool.strategy": "Estrategia de rotación",
  "accountPool.strategyDesc": "Cómo asigna OpenCodex una cuenta a una tarea nueva/no vinculada.",
  "accountPool.strategyResetFirst": "Restablecimiento más próximo primero",
  "accountPool.strategyHintResetFirst": "Prefiere el restablecimiento de 5 horas o semanal más cercano entre las cuentas por debajo del umbral de uso. Las tareas vinculadas siguen la política de afinidad configurada. Las cuotas modelo independientes utilizan la ordenación de cuotas.",
  "accountPool.strategyQuota": "Contingente",
  "accountPool.strategyRoundRobin": "Round-robin",
  "accountPool.strategyFillFirst": "Llenar primero",
  "accountPool.strategyHintQuota": "Quota enlaza una tarea existente en el umbral de uso solo cuando `pool.cacheAffinity` está desactivado (está activado de forma predeterminada). De lo contrario, las tareas vinculadas permanecerán hasta que la cuenta no pueda servir, y luego solo en el margen de cuota genuino.",
  "accountPool.strategyHintRoundRobin": "Round-robin rota solo tareas sin un enlace en vivo; el umbral de uso no cambia la rotación normal.",
  "accountPool.strategyHintFillFirst": "Fill-first utiliza el umbral como punto de drenaje para las tareas no vinculadas; las tareas vinculadas saludables mantienen la afinidad.",
  "accountPool.unboundDefinition": "Una tarea nueva o sin vincular es una solicitud sin una cuenta asignada actualmente. Una tarea existente y visible puede perder su vinculación después de restablecer el proxy o la afinidad.",
