  "cws.strategy.jev": "JEV",
  "cws.strategy.failoverHint": "Prueba los objetivos en orden. Si el primero falla con un error reintentable (límite de velocidad, interrupción, puerta de suscripción), salte al siguiente.",
  "cws.strategy.roundRobinHint": "Equilibrar el tráfico por peso. Mantenga cada destino seleccionado para un lote de solicitudes exitosas y luego avance.",
