  "cws.field.defaultEffortHint": "Se usa solo cuando el cliente omite el esfuerzo de razonamiento. Las opciones son la intersección de los esfuerzos anunciados de los objetivos seleccionados; los metadatos de los objetivos sin esfuerzo de catálogo no ofrecen ninguno.",
