  "cws.aboutTitle": "Entorno de ejecución",
  "cws.aboutBody": "Los destinos que fallan entran brevemente en un periodo de espera que respeta Retry-After. Los errores de contexto o de solicitud no provocan un cambio de destino. Cada destino adapta el esfuerzo a sus capacidades; si se agotan los destinos del combo, se rechaza la solicitud. Los registros y Uso conservan el orden de los intentos reales y el consumo de cada uno.",
  "cws.removeConfirmTitle": "¿Eliminar {model}?",
