  "cws.err.duplicateId": "Un combo con este id ya existe.",
  "cws.err.invalidAlias": "Los alias deben usar letras, números, puntos, guiones bajos o guiones con un segmento \"/\" como máximo.",
  "cws.err.aliasReservedNamespace": "El alias no debe usar el espacio de nombres reservado \"combo/\".",
