  "claudeDesktop.mode.firstPartyHint": "El escritorio permanece conectado a claude.ai. La pestaña Código usa OpenCodex cuando el equipo de escritorio está encendido; la CLI independiente tiene su propio interruptor. Ambos leen la misma configuración env.",
  "claude.intercept.start": "Iniciar interceptación",
  "claude.intercept.starting": "Iniciando intercepción…",
  "claude.intercept.reason.disabled": "Habilite el enrutamiento y la interceptación Claude primero.",
  "claude.intercept.reason.client_role": "Este proceso es un cliente hub. Habilitar la interceptación en un servidor local.",
  "claude.intercept.reason.ephemeral_port": "Establece claudeCode.intercept.port cuando el puerto público sea efímero.",
  "claude.intercept.reason.port_in_use": "El puerto {port} está en uso. Libre o cambiar claudeCode.intercept.port.",
  "claude.intercept.reason.port_mismatch": "Esta ejecución utiliza el puerto {bound}; puerto configurado {configured} difiere. Usa el puerto enlazado o restaure el valor configurado.",
  "claude.intercept.reason.failed": "La intercepción no pudo comenzar. Vuelva a intentar después de comprobar la configuración del proxy local.",
  "claude.intercept.reason.stopped": "El ciclo de vida de la intercepción se ha detenido. Inicie un servicio OpenCodex en ejecución.",
  "claude.firstParty.label": "Claude Code CLI de primera mano",
  "claude.firstParty.desc": "Permite que la claude independiente CLI mantenga su inicio de sesión Claude mientras su tráfico pasa a través del proxy de intercepción local.",
  "claude.firstParty.aria": "Alternar Claude Code CLI de primera mano",
  "claude.firstParty.risk": "Riesgo de la cuenta: la primera parte dirige el tráfico de suscripción Claude a través de un proxy de interceptación local. Anthropic puede tratar esto como una violación de los términos y suspender la cuenta.",
  "claude.firstParty.shared": "Cuando se aplica el env proxy compartido, el otro Claude cliente también transita el proxy local como un relé sin cambios; TLS termina localmente. Establecer NO_PROXY='*' en el shell para uso terminal completamente nativo.",
  "claude.firstParty.deadProxy": "La configuración de Claude env apunta a un proxy que no se está ejecutando. Inicie opencodex, o desactive Desktop/CLI first-party para eliminar la configuración antes de usar claude simple.",
  "claude.firstParty.notApplied": "CLI first-party está activado, pero no se aplican sus configuración de proxy. Comprueba la configuración de Claude env antes de usar claude simple.",
  "claude.firstParty.brokenProxy": "La intercepción no pudo comenzar. Vuelva a intentar después de comprobar la configuración del proxy local.",
  "claude.firstParty.residual": "La configuración de Claude todavía apunta a un proxy OpenCodex, aunque ni el escritorio ni la primera parte CLI están activados. Elimine la configuración de proxy restante o ejecute `ocx ensure`.",
  "claude.firstParty.routingOff": "opencodex no está sirviendo la intercepción Claude en su configuración actual (el enrutamiento Claude o la intercepción están desactivados, o esta máquina es un cliente de otro concentrador opencodex), por lo que estos configuración apuntan a un proxy que no los servirá. Vuelva a encenderlo en esta máquina o apague la configuración de primera persona para eliminar la configuración.",
  "claude.firstParty.disabled": "Habilite el enrutamiento y la interceptación Claude primero.",
  "claude.firstParty.foreign": "~/.claude/settings.json apunta al proxy opencodex pero confía en un certificado que opencodex no gestiona, por lo que las solicitudes fallan. Arreglar HTTPS_PROXY / NODE_EXTRA_CA_CERTS allí a mano.",
  "claude.firstParty.local": "~/.claude/settings.json envía Claude Code a través de un proxy local en 127.0.0.1 que opencodex no puede confirmar como propio. Si ya no lo utiliza, quitar HTTPS_PROXY allí.",
  "claude.firstParty.unknown": "opencodex no pudo determinar si ~/.claude/settings.json todavía apunta a su proxy.",
  "claude.firstParty.refusal.interceptDisabled": "El proxy de intercepción está desactivado.",
  "claude.firstParty.refusal.interceptUnavailable": "La intercepción no pudo comenzar. Vuelva a intentar después de comprobar la configuración del proxy local.",
  "claude.firstParty.refusal.foreignEnv": "Otro programa posee la configuración del proxy Claude.",
