  "claudeDesktop.mode.firstPartyRisk": "Riesgo de cuenta: la primera parte envía su tráfico de suscripción Claude a través de un proxy de intercepción local. Anthropic puede tratar esto como una violación de los términos y suspender la cuenta. Gateway es el valor predeterminado.",
  "claudeDesktop.mode.gatewayHint": "Toda la aplicación cambia a OpenCodex como su puerta de enlace. El chat se ejecuta localmente; Las características de claude.ai no están disponibles.",
  "claudeDesktop.mode.switchNote": "El cambio reemplaza la configuración del otro modo. Completamente salir y volver a abrir el escritorio después.",
