  "claudeDesktop.firstParty.bindings.hint": "Claude Desktop conserva los nombres de Anthropic en el selector de la pestaña Code. Vincula una entrada del selector con un modelo de OpenCodex para que ese modelo atienda sus solicitudes. Solo el tráfico de Claude Code que pasa por el proxy local (la pestaña Code de Desktop y la CLI claude) usa estas vinculaciones; ocx claude no cambia. Se aplican en la siguiente solicitud, sin cerrar y volver a abrir la aplicación.",
