  "remoteLink.error.trust_file_unexpected": "El archivo known_hosts de Remote Link contiene un patrón, una lista de hosts, un marcador o una línea no válida. Quita esa línea, prueba la conexión y vuelve a confirmar el host.",
  "remoteLink.error.key_cleanup_failed": "No se completó el registro y Home no pudo revocar la clave de enlace emitida. Revoca esa clave en Claves API antes de reintentar.",
  "remoteLink.error.link_cleanup_uncertain": "No se completó el registro y Home no pudo deshacerlo: se desconoce si se guardó el enlace y no se pudo revocar su clave. Si el enlace aparece aquí, desconéctalo. Si la clave de enlace permanece en Claves API, revócala.",
  "remoteLink.residual.purge": "Es posible que el Child siga conectado. Ejecuta {cmd} en el Child antes de reintentar.",
  "remoteLink.residual.purgeWindows": "Es posible que el Child siga conectado. En el Símbolo del sistema del Child, ejecuta {cmd} antes de reintentar.",
  "remoteLink.residual.purgeWindowsFallback": "Si LOCALAPPDATA no está definida, ejecuta {cmd} en su lugar.",
  "remoteLink.residual.purgeAny": "Es posible que el Child siga conectado. En macOS o Linux, ejecuta {cmd} en el Child antes de reintentar.",
  "remoteLink.residual.purgeAnyWindows": "En Windows, ejecuta {cmd} en el Símbolo del sistema del Child.",
  "remoteLink.residual.ephemeral": "Es posible que el Child siga conectado. Ejecuta {cmd} en el Child antes de reintentar.",
  "remoteLink.residual.full": "Es posible que el Child siga conectado. Ejecuta {cmd} en el Child y, si se desconecta, ejecuta ocx restart antes de reintentar.",
  "remoteLink.residual.unknown": "Es posible que el Child siga conectado. En una instalación completa, ejecuta {cmd} y, si se desconecta, ejecuta ocx restart antes de reintentar.",
  "remoteLink.residual.unknownLightweight": "Si es un Child ligero, ejecuta {cmd} en su lugar.",
  "remoteLink.residual.lightweightPlaced": "Si copiaste el ejecutable a mano, usa la ruta que muestra {cmd} (where.exe ocx-child en Windows) para ejecutar el mismo comando.",
  "remoteLink.residual.lightweightPlacedWindows": "Si copiaste el ejecutable a mano, usa la ruta que muestra {cmd} para ejecutar el mismo comando.",
  "remoteLink.residual.bound": "Cada paso solo actúa si los registros del Child indican el enlace de este intento ({linkId}) o no indican ninguno. Deja intacto cualquier Child que pertenezca a otro enlace, a un hub o a otro Home.",
  "remoteLink.residual.olderFull": "Una versión de OpenCodex anterior a esa opción la rechaza antes de modificar el enlace. En ese caso, ejecuta ocx disconnect y ocx restart solo si {cmd} muestra {linkId}, justo después de comprobarlo. De lo contrario, deja intacto el Child.",
  "remoteLink.residual.olderLightweight": "Una versión de ocx-child anterior a esa opción la rechaza antes de actuar. En ese caso, deja intacto el Child: su estado no puede mostrar la conexión interrumpida de otro enlace, y una desconexión sin esa opción la restauraría y después la quitaría.",
  "remoteLink.residual.noLink": "Es posible que el Child siga conectado. Esta respuesta no indica el ID del enlace del intento. No se puede limitar ninguna operación a ese enlace, así que deja intacto el Child.",
  "remoteLink.error.generic": "No se pudo completar la solicitud de enlace remoto.",
