  "remoteLink.workspaceMoved.title": "Remote Workspace tiene su propia página ahora",
  "remoteLink.workspaceMoved.body": "Usa la página de espacio de trabajo remoto separada.",
  "remoteLink.workspaceMoved.open": "Abrir espacio de trabajo remoto",
  "remoteLink.forceRemove.title": "Esta máquina no pudo alcanzar {alias}",
  "remoteLink.forceRemove.body": "¿Quitar el enlace solo en este equipo? Después ejecuta {cmd} en {alias}. Solo lo desconectará si {alias} sigue conectado a este enlace; mantendrá intactos los equipos de otro enlace, hub o Home.",
  "remoteLink.forceRemove.ephemeralBody": "¿Quitar el enlace solo en este equipo? Cuando {alias} responda, ejecuta {cmd} aquí. Solo actúa si los registros de {alias} indican este enlace o ninguno, y se niega a actuar en un equipo que pertenezca a otro enlace.",
  "remoteLink.forceRemove.confirm": "Eliminar aquí solamente",
  "remoteLink.forceRemoved.unknownFallback": "Cada opción solo actúa mientras el equipo pertenezca a este enlace. Una versión anterior a esa opción la rechaza antes de actuar. En una instalación completa, ejecuta primero {cmd}. Si el Child es ligero, déjalo intacto: su estado no muestra una conexión interrumpida de otro enlace, y una desconexión sin esa opción la restauraría y después la quitaría.",
  "remoteLink.forceRemoved.fullBound": "Se quitó {alias} solo en este equipo (enlace {linkId}). Cuando responda {alias}, ejecuta {cmd} allí. Solo desconectará a {alias} si sigue conectado a este enlace.",
  "remoteLink.forceRemove.refusal.expect_link_unsupported": "Usa una versión que no admite comprobar el enlace, y otro enlace de este Home podría llegar al mismo equipo.",
  "remoteLink.forceRemove.refusal.child_disconnect_pending": "Tiene una desconexión sin terminar que no pudo asociar a este enlace.",
  "remoteLink.forceRemove.refusal.child_residual": "Conserva registros que no puede restaurar. Uno podría corresponder a la conexión interrumpida de otro enlace.",
  "remoteLink.forceRemove.refusal.child_link_mismatch": "Pertenece a otro enlace, hub o Home, o hay una conexión o rotación de clave en curso, o no se pudo leer su estado.",
  "remoteLink.forceRemove.refusedTitle": "{alias} se negó a desconectarse de este enlace",
  "remoteLink.forceRemove.unknownBody": "¿Quitar el enlace solo en este equipo? Este Home no registró si {alias} usa la instalación completa o el agente ligero, por lo que no tendrá datos para recuperarlo. Las instrucciones para comprobar {alias} quedan en esta página hasta que las descartes o salgas.",
  "remoteLink.forceRemove.noteId": "Anota ahora el ID de enlace {linkId}. Una vez quitado el enlace, este Home ya no lo registrará.",
  "remoteLink.forceRemoved.ephemeral": "Se quitó {alias} solo en este equipo (enlace {linkId}). Cuando responda {alias}, ejecuta {cmd} aquí. Solo actúa si los registros de {alias} indican este enlace o ninguno, y se niega a actuar en un equipo que pertenezca a otro enlace.",
  "remoteLink.forceRemoved.fullCheck": "Una versión de OpenCodex anterior a esa opción la rechaza antes de actuar sobre el enlace. En ese caso, ejecuta {cmd} en el equipo.",
  "remoteLink.forceRemoved.fullDisconnect": "Haz la comprobación y la desconexión de inmediato, una tras otra: si se registra un enlace entre ambas, se eliminará. Ejecuta {cmd} allí solo si aparece Link: {linkId} o se indica que el equipo no está conectado. Si aparece otro enlace, hub u otro Home, o no se puede leer el estado, deja intacto el equipo. Este Home ya revocó su propio enlace.",
  "remoteLink.forceRemoved.unknownCheck": "Se quitó {alias} solo en este equipo (enlace {linkId}). Este Home no registró si usa la instalación completa o el agente ligero (ocx-child), por lo que no tendrá datos para recuperarlo. Cuando responda {alias}, ejecuta {cmd} si usa una instalación completa.",
  "remoteLink.forceRemoved.unknownLocate": "El agente de un Child ligero es ocx-child. La copia instalada por el enlace está en ~/.cache/opencodex/bin/ocx-child (en el Símbolo del sistema de Windows, %LOCALAPPDATA%\\opencodex\\bin\\ocx-child.exe o %USERPROFILE%\\.cache\\opencodex\\bin\\ocx-child.exe si LOCALAPPDATA no está definida). Una copia instalada a mano está en ~/.local/bin o en otra ubicación de PATH. {cmd} muestra la que está en PATH (where.exe ocx-child en Windows).",
  "remoteLink.forceRemoved.unknownLightweight": "En un Child ligero, ejecuta {cmd} en su lugar. Usa la ruta del ocx-child en uso si no es la copia instalada por el enlace (en Windows, la ruta de ocx-child.exe indicada arriba).",
  "remoteLink.forceRemoved.unknownDisconnect": "Haz la comprobación y la desconexión de inmediato, una tras otra: si se registra un enlace entre ambas, se eliminará. Ejecuta {cmd} allí solo si la salida indica el enlace {linkId} o que el equipo no está conectado. Si indica otro enlace, hub u otro Home, o no se puede leer el estado, deja intacto el equipo. Este Home ya revocó su propio enlace.",
